/* Figures and Latin text use Barlow (a DIN-style face made for figures);
   Chinese falls through to Noto Sans SC. unicode-range limits Barlow to
   Latin characters and digits; size-adjust matches its cap height to Noto's. */
@font-face { font-family: "Latin Metric"; font-weight: 300; font-display: block; size-adjust: 105%; unicode-range: U+0000-00FF, U+2013-2014, U+2018-201D, U+2026;
  src: url("@fontsource/barlow/files/barlow-latin-300-normal.woff2") format("woff2"); }
@font-face { font-family: "Latin Metric"; font-weight: 400; font-display: block; size-adjust: 105%; unicode-range: U+0000-00FF, U+2013-2014, U+2018-201D, U+2026;
  src: url("@fontsource/barlow/files/barlow-latin-400-normal.woff2") format("woff2"); }
@font-face { font-family: "Latin Metric"; font-weight: 500; font-display: block; size-adjust: 105%; unicode-range: U+0000-00FF, U+2013-2014, U+2018-201D, U+2026;
  src: url("@fontsource/barlow/files/barlow-latin-500-normal.woff2") format("woff2"); }
@font-face { font-family: "Latin Metric"; font-weight: 600; font-display: block; size-adjust: 105%; unicode-range: U+0000-00FF, U+2013-2014, U+2018-201D, U+2026;
  src: url("@fontsource/barlow/files/barlow-latin-600-normal.woff2") format("woff2"); }


@custom-variant dark (&:is(.dark *));

:root {
  --radius: 0.625rem;
  --background: oklch(1 0 0);
  --foreground: oklch(0.145 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.145 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.145 0 0);
  --primary: oklch(0.205 0 0);
  --primary-foreground: oklch(0.985 0 0);
  --secondary: oklch(0.97 0 0);
  --secondary-foreground: oklch(0.205 0 0);
  --muted: oklch(0.97 0 0);
  --muted-foreground: oklch(0.556 0 0);
  --accent: oklch(0.97 0 0);
  --accent-foreground: oklch(0.205 0 0);
  --destructive: oklch(0.577 0.245 27.325);
  --border: oklch(0.922 0 0);
  --input: oklch(0.922 0 0);
  --ring: oklch(0.708 0 0);
  --chart-1: oklch(0.646 0.222 41.116);
  --chart-2: oklch(0.6 0.118 184.704);
  --chart-3: oklch(0.398 0.07 227.392);
  --chart-4: oklch(0.828 0.189 84.429);
  --chart-5: oklch(0.769 0.188 70.08);
}

@theme inline {
  --font-sans: "Latin Metric", "Noto Sans SC", ui-sans-serif, system-ui, sans-serif;
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground antialiased;
    /* Chinese typesetting: trim the blank half of full-width punctuation at line
       starts and between adjacent marks, so justified lines stay even. */
    text-spacing-trim: trim-start;
    font-kerning: normal;
  }
}
=== progress
"use client"

import * as React from "react"
import { cn } from "@/lib/utils"
import { Progress as ProgressPrimitive } from "radix-ui"

// A bar that carries a count, read against a baseline: the value is the length
// of the ink laid along that line, so two counts are told apart by how far the
// bar reaches, not by a tint. The baseline is a hairline the width of the scale
// (zero to max), the same weight and grey as the table's row lines; the bar is
// one pixel of foreground ink sitting on it, so the bar reads as the inked part
// of the line and the line stays as light as every other hairline on the page.
function Progress({
  className,
  value,
  ...props
}: React.ComponentProps<typeof ProgressPrimitive.Root>) {
  return (
    <ProgressPrimitive.Root
      data-slot="progress"
      className={cn("relative h-2 w-full", className)}
      {...props}
    >
      <div
        data-slot="progress-baseline"
        className="absolute inset-x-0 bottom-0 border-b border-border"
      />
      <ProgressPrimitive.Indicator
        data-slot="progress-indicator"
        className="absolute bottom-0 left-0 border-b border-foreground transition-all"
        style={{ width: `${value || 0}%` }}
      />
    </ProgressPrimitive.Root>
  )
}

export { Progress }
